"""Object Model file for the Facilities window in the Mosaiq application"""
from interops.libraries.squish_actions import CommonActions
from interops.libraries.mosaiq.interactions.objects.mosaiq_facilities_objects import FacilitiesObjects
from interops.libraries.common.state import get_value, State

class Facilities():
    """
    Class used to model Facilities window and its operations.
    """
    def __init__(self) -> None:
        #CommonActions.wait_for_object_exists(FacilitiesObjects.facilities_Window)
        self.filerter_city = State(FacilitiesObjects.city_Edit, "")
        self.filter_state = State(FacilitiesObjects.state_Edit, "")
        self.filter_external_sources = State(FacilitiesObjects.external_source_CheckBox)

    @property
    def view(self):
        self._view = get_value(FacilitiesObjects.view_Pane)
        return self._view

    @view.setter
    def view(self, value):
        CommonActions.select_item_in_list_with_acknowledge(FacilitiesObjects.view_Pane, value)
        self._view = value

    @property
    def filter_facility(self):
        self._filter_facility = get_value(FacilitiesObjects.facility_Type_Pane)
        return self._filter_facility

    @filter_facility.setter
    def filter_facility(self, value):
        CommonActions.select_item_in_list_with_acknowledge(FacilitiesObjects.facility_Type_Pane, value)
        self._filter_facility = value

    def click_close(self):
        CommonActions.left_click_object(FacilitiesObjects.close_Button)

    def click_select(self):
        CommonActions.left_click_object(FacilitiesObjects.select_Button)

    def move_to_next(self):
        CommonActions.press_key_down_arrow()

    def move_to_pre(self):
        CommonActions.press_key_up_arrow()

    def find_view_by_name(self, name):
        CommonActions.type_in_textfield(FacilitiesObjects.find_Pane, name)